"use client";

import { useActionState, useState, useTransition } from "react";
import { addPortForward, deletePortForward } from "@/lib/actions-server";

export function AddForwardForm({ serverId }: { serverId: string }) {
  const [state, action, pending] = useActionState(addPortForward, {});
  // CONTROLLED, deliberately. React 19 resets uncontrolled fields on every
  // `<form action={fn}>` submit — including a REJECTED one. `addPortForward`
  // returns `{error}` for the common cases (port already forwarded, over the
  // 10-forward cap, privileged/invalid port), so an uncontrolled field blanked
  // the port the customer just typed at the exact moment the red error told them
  // to fix it, and reverted the protocol to TCP. Same reset as TicketForms.tsx.
  const [guestPort, setGuestPort] = useState("");
  const [protocol, setProtocol] = useState("tcp");
  return (
    <form action={action} className="flex flex-wrap items-end gap-3">
      <input type="hidden" name="serverId" value={serverId} />
      <div>
        <label className="label">Guest port</label>
        <input
          className="input w-32"
          name="guestPort"
          type="number"
          min={1}
          max={65535}
          placeholder="80"
          required
          value={guestPort}
          onChange={(e) => setGuestPort(e.target.value)}
        />
      </div>
      <div>
        <label className="label">Protocol</label>
        <select
          className="input w-28"
          name="protocol"
          value={protocol}
          onChange={(e) => setProtocol(e.target.value)}
        >
          <option value="tcp">TCP</option>
          <option value="udp">UDP</option>
        </select>
      </div>
      <button className="btn-primary" disabled={pending}>
        {pending ? "Adding…" : "Add forward"}
      </button>
      {state?.error && <p className="w-full text-sm text-red-400">{state.error}</p>}
    </form>
  );
}

const PRESETS: { label: string; guestPort: number; protocol: "tcp" | "udp"; hint: string }[] = [
  { label: "HTTP", guestPort: 80, protocol: "tcp", hint: "Web (port 80)" },
  { label: "HTTPS", guestPort: 443, protocol: "tcp", hint: "Secure web (port 443)" },
];

export function FirewallPresets({
  serverId,
  disabled,
  existingGuestPorts,
}: {
  serverId: string;
  disabled?: boolean;
  existingGuestPorts: number[];
}) {
  const [pending, start] = useTransition();
  const [error, setError] = useState<string | null>(null);
  const [busyPort, setBusyPort] = useState<number | null>(null);
  const taken = new Set(existingGuestPorts);

  const add = (guestPort: number, protocol: "tcp" | "udp") => {
    setError(null);
    setBusyPort(guestPort);
    const fd = new FormData();
    fd.set("serverId", serverId);
    fd.set("guestPort", String(guestPort));
    fd.set("protocol", protocol);
    start(async () => {
      const res = await addPortForward({}, fd);
      if (res?.error) setError(res.error);
      setBusyPort(null);
    });
  };

  return (
    <div className="space-y-3">
      <div className="flex flex-wrap gap-2">
        {PRESETS.map((p) => {
          const already = taken.has(p.guestPort);
          return (
            <button
              key={p.guestPort}
              type="button"
              className="btn-secondary px-3 py-1.5 text-sm"
              disabled={disabled || pending || already}
              title={already ? `Port ${p.guestPort} is already forwarded` : p.hint}
              onClick={() => add(p.guestPort, p.protocol)}
            >
              {busyPort === p.guestPort && pending
                ? "Adding…"
                : already
                  ? `${p.label} ✓`
                  : `Allow ${p.label} (${p.guestPort})`}
            </button>
          );
        })}
      </div>
      {error && <p className="text-sm text-red-400">{error}</p>}
      <p className="text-xs text-slate-500">
        One-click presets open a public port that forwards to the matching port inside your VM. Use
        the custom form below for any other port.
      </p>
    </div>
  );
}

export function DeleteForwardButton({ serverId, forwardId }: { serverId: string; forwardId: string }) {
  const [pending, start] = useTransition();
  return (
    <button
      className="btn-danger px-3 py-1 text-xs"
      disabled={pending}
      onClick={() => {
        if (window.confirm("Remove this port forward? Connections to the public port will stop working."))
          start(() => deletePortForward(serverId, forwardId));
      }}
    >
      {pending ? "…" : "Remove"}
    </button>
  );
}

import { execFile } from "node:child_process";
import { promisify } from "node:util";
import { db } from "../lib/db";
import {
  planNatRules,
  reconcileNatChain,
  ruleSpec,
  type ForwardSource,
  type NatHost,
  type NatRule,
  type NatSyncResult,
} from "../lib/nat-rules";

const exec = promisify(execFile);

const CHAIN = process.env.NXEON_NAT_CHAIN ?? "NXEON_FWD";

async function iptables(args: string[]) {
  await exec("iptables", args);
}

async function ensureChain() {
  try {
    await iptables(["-t", "nat", "-N", CHAIN]);
  } catch {
    /* chain exists */
  }
  // Ensure PREROUTING jumps to our chain exactly once — this is the path for
  // EXTERNAL clients (real customers) reaching a NAT guest's forwarded port.
  try {
    await iptables(["-t", "nat", "-C", "PREROUTING", "-j", CHAIN]);
  } catch {
    await iptables(["-t", "nat", "-A", "PREROUTING", "-j", CHAIN]);
  }
  // Also jump from OUTPUT for HOST-LOCAL traffic aimed at our own public IP.
  // PREROUTING DNAT never fires for packets a process on THIS box originates, so
  // the platform's own ops that connect to <PUBLIC_IP>:<forwarded-port> — SSL
  // issuance, migration remediation, backups, the Claude backfill — were hitting
  // the host's own (empty) port and getting ECONNREFUSED for every NAT server.
  // Scoping the jump to `-d <PUBLIC_IP>` means only traffic addressed to the
  // public IP is redirected; host-local :port traffic to anything else is
  // untouched, and the shared DNAT rules only match ports that actually forward.
  const publicIp = (process.env.PUBLIC_IP ?? "").trim();
  if (publicIp) {
    try {
      await iptables(["-t", "nat", "-C", "OUTPUT", "-d", publicIp, "-j", CHAIN]);
    } catch {
      await iptables(["-t", "nat", "-A", "OUTPUT", "-d", publicIp, "-j", CHAIN]);
    }
  }
}

/**
 * The real, iptables-backed NatHost — the only implementation production uses.
 * The decision logic it is handed to lives in lib/nat-rules.ts and is tested
 * against an in-memory fake; see the H5 incident note at the top of that file.
 */
function iptablesHost(): NatHost {
  return {
    ensureChain,
    listChain: async () => {
      const { stdout } = await exec("iptables", ["-t", "nat", "-S", CHAIN]);
      return stdout;
    },
    addRule: (r: NatRule) => iptables(["-t", "nat", "-A", CHAIN, ...ruleSpec(r)]),
    deleteRule: (r: NatRule) => iptables(["-t", "nat", "-D", CHAIN, ...ruleSpec(r)]),
  };
}

/**
 * Reconcile the NXEON_FWD chain with the database, and verify the result.
 *
 * This used to open with `iptables -t nat -F NXEON_FWD` and rebuild the chain in
 * an unguarded loop, so a single failed `-A` aborted the rebuild and left every
 * subsequent server with no DNAT rule — a fleet-wide SSH blackhole that reported
 * DONE, because DONE meant "the last iptables call exited 0" (incident H5).
 *
 * There is no flush now. `reconcileNatChain` reads the chain, applies only the
 * difference, then reads it BACK and throws with the exact missing rules and the
 * command to inspect them if the kernel does not hold what the database says it
 * should. Rules that were already correct are never removed, so no failure in
 * this path can take down a customer who was working before it ran.
 *
 * Throws on an unproven ruleset — callers that cannot tolerate a throw must say
 * so; `remove()` in worker/index.ts calls this after deleting the server row, so
 * a throw there re-queues DELETE onto a row that no longer exists. That caller
 * uses `syncPortForwardsBestEffort` below.
 */
export async function syncPortForwards(): Promise<NatSyncResult> {
  const servers = await db.server.findMany({
    where: {
      ipAddress: { not: null },
      sshPort: { not: null },
      status: { notIn: ["SUSPENDED", "DELETING"] },
    },
    include: { portForwards: true },
  });

  const intent = planNatRules(servers as unknown as ForwardSource[]);

  // Two data problems that used to be invisible because the old loop just built
  // whatever it was handed. Neither blocks the sync — the ruleset we install is
  // still verified end to end — but neither is swallowed either.
  for (const c of intent.conflicts) {
    console.error(
      `[nat] port collision: ${c.proto}/${c.dport} is claimed by ${c.winner} and also by ` +
        `${c.losers.join(", ")}. Only ${c.winner} is forwarded; the others get NOTHING on that port.`
    );
  }
  for (const r of intent.rejected) {
    console.error(`[nat] ${r.hostname}: no rule installed — ${r.reason}`);
  }

  const result = await reconcileNatChain(iptablesHost(), CHAIN, intent);
  if (result.unparsed.length) {
    console.warn(
      `[nat] ${CHAIN} contains ${result.unparsed.length} rule(s) this engine did not write and ` +
        `will not touch: ${result.unparsed.slice(0, 5).join(" | ")}`
    );
  }
  console.log(
    `[nat] ${CHAIN} verified: ${result.verified} rule(s) present (+${result.added} / -${result.deleted})`
  );
  return result;
}

/**
 * For callers that must not be re-queued by a sync failure (server DELETE runs
 * this after the row is gone, so a throw dies on "Server not found" on retry and
 * the sync is never re-attempted — H5's aggravating factor).
 *
 * It still never claims success: the failure is logged in full and returned, so
 * the caller can surface it. What it will not do is convert a networking problem
 * into a stuck job that hides it.
 */
export async function syncPortForwardsBestEffort(context: string): Promise<Error | null> {
  try {
    await syncPortForwards();
    return null;
  } catch (e: any) {
    console.error(`[nat] port-forward sync FAILED after ${context} — forwarding may be wrong: ${e?.message ?? e}`);
    return e instanceof Error ? e : new Error(String(e));
  }
}

