async function ownedServer(serverId: string) {
  const user = await requireUser();
  const server = await db.server.findUnique({ where: { id: serverId }, include: { plan: true } });
  if (!server) throw new Error("Not found");
  if (server.userId !== user.id && user.role !== "ADMIN") throw new Error("Forbidden");
  return { user, server };
}

async function queueJob(
  serverId: string,
  type:
    | "SNAPSHOT_CREATE"
    | "SNAPSHOT_DELETE"
    | "SNAPSHOT_ROLLBACK"
    | "BACKUP_CREATE"
    | "RESIZE"
    | "PASSWORD_RESET",
  payload?: Record<string, unknown>
): Promise<{ error?: string }> {
  const pending = await db.job.count({
    where: { serverId, status: { in: ["QUEUED", "RUNNING"] } },
  });
  if (pending > 0) return { error: "Another operation is already in progress on this server." };
  await db.job.create({ data: { type, serverId, payload: payload as any } });
  return {};
}

