"use server";

import { revalidatePath } from "next/cache";
import { db } from "./db";
import { requireUser } from "./auth";
import { validateRule, FW_ACTIONS, FW_PROTOCOLS } from "./firewall-rules";
import type { FirewallAction, FirewallProtocol } from "@prisma/client";

/**
 * Inbound firewall (security-group) rules for a customer's VPS.
 *
 * Ownership is enforced exactly like the port-forward actions: `ownedServer`
 * throws unless the caller owns the server (or is an admin). Every mutable field
 * is validated + normalised by lib/firewall-rules.ts BEFORE it is persisted, and
 * again in the worker before it reaches a shell. Each change enqueues a
 * SYNC_FIREWALL job that re-applies the FULL rule set idempotently on the guest.
 */

const MAX_RULES_PER_SERVER = 50;

async function ownedServer(serverId: string) {
  const user = await requireUser();
  const server = await db.server.findUnique({ where: { id: serverId } });
  if (!server) throw new Error("Not found");
  if (server.userId !== user.id && user.role !== "ADMIN") throw new Error("Forbidden");
  return { user, server };
}

async function enqueueSync(serverId: string) {
  await db.job.create({ data: { type: "SYNC_FIREWALL", serverId } });
}

export async function listFirewallRules(serverId: string) {
  await ownedServer(serverId);
  return db.firewallRule.findMany({
    where: { serverId },
    orderBy: [{ position: "asc" }, { createdAt: "asc" }],
  });
}

export async function addFirewallRule(prev: any, formData: FormData): Promise<{ error?: string }> {
  const serverId = String(formData.get("serverId") ?? "");
  const { user } = await ownedServer(serverId);

  // VALIDATE everything before it is persisted. `validateRule` is the same gate
  // the worker uses, so a rule this action accepts is guaranteed buildable.
  const result = validateRule({
    action: formData.get("action"),
    protocol: formData.get("protocol"),
    portFrom: formData.get("portFrom"),
    portTo: formData.get("portTo"),
    sourceCidr: formData.get("sourceCidr"),
  });
  if (!result.ok) return { error: result.error };

  // `comment` is customer free text — persisted + shown, NEVER shell-bound.
  const comment = String(formData.get("comment") ?? "").trim().slice(0, 200) || null;

  const count = await db.firewallRule.count({ where: { serverId } });
  if (count >= MAX_RULES_PER_SERVER) {
    return { error: `Limit of ${MAX_RULES_PER_SERVER} firewall rules reached. Delete one first.` };
  }

  const last = await db.firewallRule.findFirst({
    where: { serverId },
    orderBy: { position: "desc" },
    select: { position: true },
  });
  const position = (last?.position ?? -1) + 1;

  const { action, protocol, portFrom, portTo, sourceCidr } = result.rule;
  await db.firewallRule.create({
    data: {
      serverId,
      direction: "INBOUND",
      action: action as FirewallAction,
      protocol: protocol as FirewallProtocol,
      portFrom,
      portTo,
      sourceCidr,
      comment,
      enabled: true,
      position,
    },
  });

  await enqueueSync(serverId);
  await db.auditLog.create({
    data: {
      userId: user.id,
      action: "server.firewall_add",
      detail: `${serverId} ${action} ${protocol} ${portFrom ?? "*"}-${portTo ?? "*"} from ${sourceCidr}`,
    },
  });
  revalidatePath(`/dashboard/servers/${serverId}`);
  return {};
}

export async function toggleFirewallRule(serverId: string, ruleId: string): Promise<{ error?: string }> {
  const { user } = await ownedServer(serverId);
  const rule = await db.firewallRule.findFirst({ where: { id: ruleId, serverId } });
  if (!rule) return { error: "Rule not found." };
  await db.firewallRule.update({ where: { id: rule.id }, data: { enabled: !rule.enabled } });
  await enqueueSync(serverId);
  await db.auditLog.create({
    data: { userId: user.id, action: "server.firewall_toggle", detail: `${serverId} ${ruleId} -> ${!rule.enabled}` },
  });
  revalidatePath(`/dashboard/servers/${serverId}`);
  return {};
}

export async function deleteFirewallRule(serverId: string, ruleId: string): Promise<{ error?: string }> {
  const { user } = await ownedServer(serverId);
  await db.firewallRule.deleteMany({ where: { id: ruleId, serverId } });
  await enqueueSync(serverId);
  await db.auditLog.create({
    data: { userId: user.id, action: "server.firewall_delete", detail: `${serverId} ${ruleId}` },
  });
  revalidatePath(`/dashboard/servers/${serverId}`);
  return {};
}

/**
 * Reorder rules by an explicit list of rule ids (new first-match order). Only
 * ids that actually belong to the server are moved; anything else is ignored, so
 * a caller cannot reposition another tenant's rule.
 */
export async function reorderFirewallRules(serverId: string, orderedIds: string[]): Promise<{ error?: string }> {
  const { user } = await ownedServer(serverId);
  if (!Array.isArray(orderedIds) || orderedIds.length === 0) return { error: "Nothing to reorder." };

  const owned = await db.firewallRule.findMany({ where: { serverId }, select: { id: true } });
  const ownedIds = new Set(owned.map((r) => r.id));
  const ids = orderedIds.filter((id) => ownedIds.has(id));
  if (ids.length === 0) return { error: "No matching rules to reorder." };

  await db.$transaction(
    ids.map((id, index) =>
      db.firewallRule.update({ where: { id }, data: { position: index } })
    )
  );

  await enqueueSync(serverId);
  await db.auditLog.create({
    data: { userId: user.id, action: "server.firewall_reorder", detail: `${serverId} ${ids.length} rules` },
  });
  revalidatePath(`/dashboard/servers/${serverId}`);
  return {};
}

/** Exposed for the UI so the add-rule <select>s stay in lockstep with the enums. */
export async function firewallOptions() {
  return { actions: FW_ACTIONS, protocols: FW_PROTOCOLS };
}

