import { execFile } from "node:child_process";
import { promisify } from "node:util";
import { db } from "../lib/db";
import { serverRootPassword } from "../lib/sftp";
import { SANDBOX } from "../lib/sandbox";
import { validateRule, buildReconcileScript, FW_CHAIN, type ValidatedRule } from "../lib/firewall-rules";
import type { Job } from "@prisma/client";

const execFileAsync = promisify(execFile);
const CMD_TIMEOUT_MS = 60_000;

/**
 * Apply a customer's inbound firewall to their guest, idempotently.
 *
 * MECHANISM: guest-side iptables over SSH, mirroring how the platform already
 * reaches VMs (worker/claude.ts, worker/ssl.ts — sshpass + execFile ARRAY args,
 * never a shell string on the host). The Proxmox per-VM firewall API was the
 * alternative, but lib/proxmox.ts exposes only a generic REST client with no
 * firewall helper, and enabling it requires flipping cluster/node/NIC firewall
 * flags that interact with the existing NAT model — a far larger, riskier change
 * for guests that are already reachable as root over SSH. So: guest iptables.
 *
 * SAFETY: the reconcile SCRIPT is built by lib/firewall-rules.ts from VALIDATED,
 * structured fields only. Each DB row is re-run through `validateRule` here
 * (defence in depth) before it can contribute a line; a row that fails is skipped
 * and logged, never interpolated. Ports are integers, protocol/action are closed
 * enums, and the source CIDR is regex-validated + normalised — so no raw customer
 * string (the free-text `comment` least of all) ever reaches the guest shell.
 *
 * IDEMPOTENT: the script creates the NXEON_FW chain once, ensures INPUT jumps to
 * it once, then FLUSHES only that chain and rebuilds it — so re-running yields
 * identical kernel state and never accumulates stale rules or touches the
 * customer's own INPUT rules.
 *
 * ANTI-LOCKOUT: the baseline always accepts loopback, ESTABLISHED/RELATED and
 * tcp/22, so SSH stays reachable no matter what the customer configures, and the
 * default DROP is appended only when they have at least one ALLOW rule.
 */
export async function syncFirewall(job: Job): Promise<void> {
  const serverId = job.serverId;
  if (!serverId) throw new Error("syncFirewall: job has no serverId");

  const server = await db.server.findUnique({
    where: { id: serverId },
    include: { firewallRules: { orderBy: [{ position: "asc" }, { createdAt: "asc" }] } },
  });
  if (!server) {
    // Row is gone (server deleted); the cascade removed its rules too. Nothing to do.
    console.log(`[fw] server ${serverId} not found — skipping firewall sync`);
    return;
  }

  // Don't fight the lifecycle: a suspended/deleting/not-yet-provisioned VM has no
  // reachable guest to configure. The rules stay in the DB and re-apply on the
  // next sync once the server is steady again.
  if (["SUSPENDED", "DELETING", "PENDING", "PROVISIONING", "ERROR"].includes(server.status)) {
    console.log(`[fw] server ${serverId} status=${server.status} — deferring firewall sync`);
    return;
  }

  // Re-validate every ENABLED row through the SAME gate the action used. A row
  // that somehow got into the DB malformed is dropped from the applied set (and
  // reported) rather than allowed to break the build.
  const validated: ValidatedRule[] = [];
  for (const r of server.firewallRules) {
    if (!r.enabled) continue;
    const result = validateRule({
      action: r.action,
      protocol: r.protocol,
      portFrom: r.portFrom,
      portTo: r.portTo,
      sourceCidr: r.sourceCidr,
    });
    if (!result.ok) {
      console.error(`[fw] server ${serverId} rule ${r.id} rejected at apply: ${result.error}`);
      continue;
    }
    validated.push(result.rule);
  }

  const script = buildReconcileScript(validated);

  if (SANDBOX) {
    console.log(`[fw] SANDBOX — would apply ${validated.length} rule(s) to ${server.hostname}:\n${script}`);
    return;
  }

  const password = serverRootPassword(server);
  if (!server.ipAddress || !password) {
    throw new Error(`syncFirewall: server ${serverId} has no reachable IP or root password`);
  }

  // sshpass + execFile ARRAY args: the script travels as a single-quoted payload
  // to `bash -c` on the guest; nothing here is assembled by a host shell.
  const args = [
    "-p",
    password,
    "ssh",
    "-o",
    "StrictHostKeyChecking=no",
    "-o",
    "UserKnownHostsFile=/dev/null",
    "-o",
    "ConnectTimeout=10",
    `root@${server.ipAddress}`,
    `bash -c ${shSingleQuote(script)}`,
  ];

  try {
    await execFileAsync("sshpass", args, {
      timeout: CMD_TIMEOUT_MS,
      maxBuffer: 4 * 1024 * 1024,
      env: { ...process.env, DEBIAN_FRONTEND: "noninteractive" },
    });
  } catch (e: any) {
    const out = `${e?.stdout ?? ""}${e?.stderr ? `\n${e.stderr}` : ""}`.trim();
    throw new Error(
      `syncFirewall: applying ${FW_CHAIN} to ${server.hostname} failed — ${e?.killed ? "timed out" : `exit ${e?.code ?? "?"}`}` +
        (out ? `: ${out.slice(0, 400)}` : "")
    );
  }

  console.log(`[fw] applied ${validated.length} rule(s) to ${server.hostname} (${FW_CHAIN})`);
}

/** Single-quote a payload for a POSIX shell (`'` → `'\''`). */
function shSingleQuote(s: string): string {
  return `'${s.replace(/'/g, `'\\''`)}'`;
}

