/* ============================ Inbound firewall ============================ */

export type FirewallRuleView = {
  id: string;
  action: string; // "ALLOW" | "DENY"
  protocol: string; // "TCP" | "UDP" | "ICMP" | "ALL"
  portFrom: number | null;
  portTo: number | null;
  sourceCidr: string | null;
  comment: string | null;
  enabled: boolean;
};

function portLabel(rule: FirewallRuleView): string {
  if (rule.protocol === "ICMP" || rule.protocol === "ALL") return "—";
  if (rule.portFrom == null && rule.portTo == null) return "all";
  if (rule.portFrom === rule.portTo) return String(rule.portFrom);
  return `${rule.portFrom}–${rule.portTo}`;
}

export function AddFirewallRuleForm({ serverId }: { serverId: string }) {
  const [state, action, pending] = useActionState(addFirewallRule, {} as { error?: string });
  // Controlled fields for the same reason AddForwardForm is: React 19 resets an
  // uncontrolled `<form action={fn}>` on every submit, including a rejected one,
  // which would wipe what the customer typed at the exact moment the inline error
  // asks them to fix it.
  const [act, setAct] = useState("ALLOW");
  const [protocol, setProtocol] = useState("TCP");
  const [portFrom, setPortFrom] = useState("");
  const [portTo, setPortTo] = useState("");
  const [sourceCidr, setSourceCidr] = useState("0.0.0.0/0");
  const [comment, setComment] = useState("");
  const portsDisabled = protocol === "ICMP" || protocol === "ALL";

  return (
    <form action={action} className="flex flex-wrap items-end gap-3">
      <input type="hidden" name="serverId" value={serverId} />
      <div>
        <label className="label">Action</label>
        <select className="input w-28" name="action" value={act} onChange={(e) => setAct(e.target.value)}>
          {FW_ACTIONS.map((a) => (
            <option key={a} value={a}>
              {a === "ALLOW" ? "Allow" : "Deny"}
            </option>
          ))}
        </select>
      </div>
      <div>
        <label className="label">Protocol</label>
        <select
          className="input w-28"
          name="protocol"
          value={protocol}
          onChange={(e) => setProtocol(e.target.value)}
        >
          {FW_PROTOCOLS.map((p) => (
            <option key={p} value={p}>
              {p}
            </option>
          ))}
        </select>
      </div>
      <div>
        <label className="label">Port from</label>
        <input
          className="input w-24"
          name="portFrom"
          type="number"
          min={1}
          max={65535}
          placeholder="e.g. 443"
          disabled={portsDisabled}
          value={portFrom}
          onChange={(e) => setPortFrom(e.target.value)}
        />
      </div>
      <div>
        <label className="label">Port to</label>
        <input
          className="input w-24"
          name="portTo"
          type="number"
          min={1}
          max={65535}
          placeholder="(optional)"
          disabled={portsDisabled}
          value={portTo}
          onChange={(e) => setPortTo(e.target.value)}
        />
      </div>
      <div>
        <label className="label">Source (CIDR)</label>
        <input
          className="input w-40"
          name="sourceCidr"
          placeholder="0.0.0.0/0"
          value={sourceCidr}
          onChange={(e) => setSourceCidr(e.target.value)}
        />
      </div>
      <div>
        <label className="label">Comment</label>
        <input
          className="input w-44"
          name="comment"
          placeholder="e.g. office IP"
          maxLength={200}
          value={comment}
          onChange={(e) => setComment(e.target.value)}
        />
      </div>
      <button className="btn-primary" disabled={pending}>
        {pending ? "Adding…" : "Add rule"}
      </button>
      {state?.error && <p className="w-full text-sm text-red-400">{state.error}</p>}
      <p className="w-full text-xs text-slate-500">
        Leave the ports blank to match every port for that protocol. Once you add an <b>Allow</b> rule
        the firewall switches to a whitelist: anything not explicitly allowed is dropped. SSH (port 22)
        is <b>always</b> kept reachable so a rule can never lock you out.
      </p>
    </form>
  );
}

export function FirewallRuleActions({ serverId, rule }: { serverId: string; rule: FirewallRuleView }) {
  const [pending, start] = useTransition();
  const [error, setError] = useState<string | null>(null);
  return (
    <div className="flex items-center justify-end gap-2">
      <button
        type="button"
        className="btn-secondary px-3 py-1 text-xs"
        disabled={pending}
        title={rule.enabled ? "Disable this rule" : "Enable this rule"}
        onClick={() => {
          setError(null);
          start(async () => {
            const res = await toggleFirewallRule(serverId, rule.id);
            if (res?.error) setError(res.error);
          });
        }}
      >
        {pending ? "…" : rule.enabled ? "Disable" : "Enable"}
      </button>
      <button
        type="button"
        className="btn-danger px-3 py-1 text-xs"
        disabled={pending}
        onClick={() => {
          if (!window.confirm("Delete this firewall rule? It will be removed from your server on the next sync.")) return;
          setError(null);
          start(async () => {
            const res = await deleteFirewallRule(serverId, rule.id);
            if (res?.error) setError(res.error);
          });
        }}
      >
        {pending ? "…" : "Delete"}
      </button>
      {error && <span className="text-xs text-red-400">{error}</span>}
    </div>
  );
}

/** Small helper the server page uses to render the port/source cells consistently. */
export function firewallPortLabel(rule: FirewallRuleView): string {
  return portLabel(rule);
}

